'use strict';

// MODULES //

var tape = require( 'tape' );
var Float64Array = require( '@stdlib/array/float64' );
var dgttrf = require( './../lib/main.js' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.equal( typeof dgttrf, 'function', 'main export is a function' );
	t.end();
} );

tape( 'dgttrf: LU factorization of tridiagonal matrix', function testLU( t ) {
	var out;
	var du;
	var dl;
	var d;

	dl = new Float64Array( [ 2.0, 3.0 ] );
	d = new Float64Array( [ 4.0, 5.0, 6.0 ] );
	du = new Float64Array( [ 1.0, 2.0 ] );
	out = dgttrf( dl, d, du );

	t.ok( out, 'returns an object' );
	t.equal( out.dl.length, 2, 'dl length' );
	t.equal( out.d.length, 3, 'd length' );
	t.equal( out.du.length, 2, 'du length' );
	t.equal( out.du2.length, 1, 'du2 length' );
	t.equal( out.ipiv.length, 3, 'ipiv length' );
	t.end();
} );

tape( 'dgttrf: 2x2 matrix, no pivoting', function test2x2NoPivot( t ) {
	var out;
	var arr;
	var du;
	var dl;
	var d;

	dl = new Float64Array( [ 3.0 ] );
	d = new Float64Array( [ 2.0, 4.0 ] );
	du = new Float64Array( [ 1.0 ] );
	out = dgttrf( dl, d, du );
	arr = function arr( x ) {
		var outArr = [];
		var i;
		for ( i = 0; i < x.length; i++ ) {
			outArr.push( x[ i ] );
		}
		return outArr;
	};

	t.deepEqual( arr( out.dl ), [ 0.6666666666666666 ], 'dl (L multipliers, LAPACK)' );
	t.deepEqual( arr( out.d ), [ 3.0, -1.6666666666666665 ], 'd (U diagonal, LAPACK)' );
	t.deepEqual( arr( out.du ), [ 4.0 ], 'du (U super-diagonal, LAPACK)' );
	t.deepEqual( arr( out.du2 ), [], 'du2 (second super-diagonal)' );
	t.deepEqual( arr( out.ipiv ), [ 1, 1 ], 'ipiv (pivot indices, LAPACK)' );
	t.end();
} );

tape( 'dgttrf: 2x2 matrix, with pivoting', function test2x2Pivot( t ) {
	var out;
	var arr;
	var du;
	var dl;
	var d;

	dl = new Float64Array( [ 3.0 ] );
	d = new Float64Array( [ 1.0, 4.0 ] );
	du = new Float64Array( [ 2.0 ] );
	out = dgttrf( dl, d, du );
	arr = function arr( x ) {
		var outArr = [];
		var i;
		for ( i = 0; i < x.length; i++ ) {
			outArr.push( x[ i ] );
		}
		return outArr;
	};

	t.deepEqual( arr( out.dl ), [ 0.3333333333333333 ], 'dl (L multipliers, LAPACK)' );
	t.deepEqual( arr( out.d ), [ 3.0, 0.6666666666666667 ], 'd (U diagonal, LAPACK)' );
	t.deepEqual( arr( out.du ), [ 4.0 ], 'du (U super-diagonal, LAPACK)' );
	t.deepEqual( arr( out.du2 ), [], 'du2 (second super-diagonal)' );
	t.deepEqual( arr( out.ipiv ), [ 1, 1 ], 'ipiv (pivot indices, LAPACK)' );
	t.end();
} );

tape( 'dgttrf: 1x1 matrix', function test1x1( t ) {
	var out;
	var arr;
	var du;
	var dl;
	var d;

	dl = new Float64Array( [] );
	d = new Float64Array( [ 5.0 ] );
	du = new Float64Array( [] );
	out = dgttrf( dl, d, du );
	arr = function arr( x ) {
		var outArr = [];
		var i;
		for ( i = 0; i < x.length; i++ ) {
			outArr.push( x[ i ] );
		}
		return outArr;
	};

	t.deepEqual( arr( out.dl ), [], 'dl (L multipliers)' );
	t.deepEqual( arr( out.d ), [ 5.0 ], 'd (U diagonal)' );
	t.deepEqual( arr( out.du ), [], 'du (U super-diagonal)' );
	t.deepEqual( arr( out.du2 ), [], 'du2 (second super-diagonal)' );
	t.deepEqual( arr( out.ipiv ), [ 0 ], 'ipiv (pivot indices)' );
	t.equal( out.info, 0, 'info should be 0 for nonsingular 1x1' );
	t.end();
} );

tape( 'dgttrf: throws on invalid input sizes', function testInvalidInput( t ) {
	var du;
	var dl;
	var d;

	dl = new Float64Array( [ 1.0, 2.0 ] );
	d = new Float64Array( [ 1.0, 2.0 ] );
	du = new Float64Array( [ 1.0 ] );

	t.throws( function throwsFn() {
		dgttrf( dl, d, du );
	}, /lengths n-1/, 'throws on invalid input sizes' );
	t.end();
} );

tape( 'dgttrf: returns info > 0 on singular matrix', function testSingular( t ) {
	var out;
	var du;
	var dl;
	var d;

	dl = new Float64Array( [ 0.0, 0.0 ] );
	d = new Float64Array( [ 0.0, 0.0, 0.0 ] );
	du = new Float64Array( [ 0.0, 0.0 ] );
	out = dgttrf( dl, d, du );

	t.ok( out.info > 0, 'info > 0 for singular matrix' );
	t.end();
} );

tape( 'dgttrf: returns info > 0 on NaN in input', function testNaNInput( t ) {
	var out;
	var du;
	var dl;
	var d;

	dl = new Float64Array( [ NaN, 2.0 ] );
	d = new Float64Array( [ 1.0, NaN, 3.0 ] );
	du = new Float64Array( [ 2.0, NaN ] );
	out = dgttrf( dl, d, du );

	t.ok( out.info > 0, 'info > 0 for NaN in input' );
	t.end();
} );

tape( 'dgttrf: returns info > 0 on NaN in sub/super-diagonal', function testNaNDiag( t ) {
	var out;
	var du;
	var dl;
	var d;

	dl = new Float64Array( [ 1.0, NaN ] );
	d = new Float64Array( [ 2.0, 3.0, 4.0 ] );
	du = new Float64Array( [ NaN, 1.0 ] );
	out = dgttrf( dl, d, du );

	t.ok( out.info > 0, 'info > 0 for NaN in sub/super-diagonal' );
	t.end();
} );
